// Council HIBRIDO: hard checks deterministas + 2 jueces LLM para razonamiento blando.
const body = $input.first().json.body || {};
const pregunta = body.pregunta || '';
const respuesta = body.respuesta || '';
const contexto = body.contexto || '';
const citasDisponibles = body.citas || [];

// === HARD CHECKS (codigo deterministico, 0 tokens LLM) ===

function extractCitations(text) {
  const re = /\[([^,\]]+?),\s*pag(?:ina)?\.?\s*(\d+)(?:\/\d+)?\]/gi;
  const out = [];
  let m;
  while ((m = re.exec(text)) !== null) {
    out.push({ raw: m[0], archivo: m[1].trim(), pagina: parseInt(m[2], 10) });
  }
  return out;
}

function extractNumbers(text) {
  // numeros con unidades: 180, 1.500, 25%, 5 millones USD, 2026
  const re = /\b(\d{1,3}(?:[\.,]\d{3})+(?:[\.,]\d+)?|\d+(?:[\.,]\d+)?)\s*(%|USD|EUR|millones?|miles?|km|kg|m2|años?)?\b/gi;
  const out = [];
  let m;
  while ((m = re.exec(text)) !== null) {
    const num = m[1];
    const unidad = m[2] || null;
    // Ignorar numeros muy genericos (1 digito sin unidad)
    if (num.length < 2 && !unidad) continue;
    out.push({ raw: m[0].trim(), numero: num, unidad });
  }
  return out;
}

function extractEntities(text) {
  // Capitalized word sequences (potential proper nouns)
  const re = /\b([A-ZÁÉÍÓÚÑ][a-záéíóúñ]+(?:\s+(?:de|del|de la|y|&)?\s*[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+){0,3})\b/g;
  const stopwords = new Set([
    'El','La','Los','Las','Un','Una','Esto','Esta','Ese','Esa','Aquel','Aquella',
    'Por','Para','Sin','Con','Si','No','Cual','Cuales','Como','Donde','Cuando','Que','Quien',
    'Segun','Asi','Tambien','Ademas','Sin embargo','Pero','Aunque','Cada','Todo','Todos',
    'Observacion','Nota','Importante','Resumen','Conclusion','Introduccion'
  ]);
  const out = new Set();
  let m;
  while ((m = re.exec(text)) !== null) {
    const ent = m[1];
    const firstWord = ent.split(/\s+/)[0];
    if (stopwords.has(firstWord)) continue;
    if (ent.length < 4) continue;
    out.add(ent);
  }
  return Array.from(out);
}

function normalize(s) {
  return String(s).toLowerCase().replace(/[\.,](?=\d{3}(?:\D|$))/g, '').replace(/\s+/g, ' ').trim();
}

function verifyCitation(cita, citasDisp) {
  const arLow = cita.archivo.toLowerCase().trim();
  return citasDisp.some(c => {
    const cAr = (c.archivo || '').toLowerCase();
    const archivoMatch = cAr === arLow || cAr.includes(arLow) || arLow.includes(cAr.replace(/\.[^.]+$/, ''));
    return archivoMatch && Number(c.pagina) === cita.pagina;
  });
}

function verifyNumber(num, contextoNorm) {
  const target = normalize(num.numero);
  return contextoNorm.includes(target);
}

function verifyEntity(ent, contextoNorm) {
  return contextoNorm.includes(ent.toLowerCase());
}

const contextoNorm = normalize(contexto);

// Extraer y verificar
const citasRespuesta = extractCitations(respuesta);
const numerosRespuesta = extractNumbers(respuesta);
const entidadesRespuesta = extractEntities(respuesta);

const checkCitas = citasRespuesta.map(c => ({
  cita: c.raw,
  archivo: c.archivo,
  pagina: c.pagina,
  valida: verifyCitation(c, citasDisponibles),
}));
const checkNumeros = numerosRespuesta.map(n => ({
  numero: n.raw,
  encontrado: verifyNumber(n, contextoNorm),
}));
const checkEntidades = entidadesRespuesta.map(e => ({
  entidad: e,
  encontrada: verifyEntity(e, contextoNorm),
}));

const citasInvalidas = checkCitas.filter(c => !c.valida);
const numerosNoEncontrados = checkNumeros.filter(n => !n.encontrado);
const entidadesNoEncontradas = checkEntidades.filter(e => !e.encontrada);

const hardScore = {
  citas_ok: `${checkCitas.length - citasInvalidas.length}/${checkCitas.length}`,
  numeros_ok: `${checkNumeros.length - numerosNoEncontrados.length}/${checkNumeros.length}`,
  entidades_ok: `${checkEntidades.length - entidadesNoEncontradas.length}/${checkEntidades.length}`,
};

const hardOk = citasInvalidas.length === 0 && numerosNoEncontrados.length === 0;

// === SOFT CHECKS (2 LLM jueces en paralelo para lo que requiere razonamiento) ===

async function callJudge(model, systemPrompt, userPrompt) {
  const t0 = Date.now();
  try {
    const data = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: {
        'Authorization': `Bearer ${$env.OPENROUTER_API_KEY}`,
        'Content-Type': 'application/json',
        'HTTP-Referer': 'http://localhost',
        'X-Title': 'CoWorkerIA Council',
      },
      body: { model, messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt },
      ], max_tokens: 800, temperature: 0 },
      json: true,
    });
    const ms = Date.now() - t0;
    const raw = data.choices?.[0]?.message?.content || '{}';
    let parsed;
    try { parsed = JSON.parse(raw); }
    catch {
      const cleaned = raw.replace(/^```(?:json)?\s*/gm, '').replace(/```\s*$/gm, '').trim();
      try { parsed = JSON.parse(cleaned); }
      catch {
        let depth = 0, start = -1, found = null;
        for (let i = 0; i < cleaned.length; i++) {
          if (cleaned[i] === '{') { if (depth === 0) start = i; depth++; }
          else if (cleaned[i] === '}') { depth--; if (depth === 0 && start !== -1) { found = cleaned.slice(start, i + 1); break; } }
        }
        parsed = found ? (() => { try { return JSON.parse(found); } catch { return { error: 'parse fail' }; } })() : { error: 'no JSON' };
      }
    }
    return { juez: model, ms, ...parsed };
  } catch (e) {
    return { juez: model, error: (e?.message || String(e)).slice(0, 200), ms: Date.now() - t0 };
  }
}
const boundCall = callJudge.bind(this);

// Juez de completitud (Sonnet 4): omitio info critica?
const completitudPrompt = `Eres juez de RAG. Te paso pasajes recuperados + respuesta generada. 
Evalua SOLO si la respuesta OMITE informacion critica de los pasajes que responderia mejor la pregunta del usuario.
NO evalues invenciones (eso lo hacemos en otro lado). Solo: "¿la respuesta es completa segun los pasajes?"

Devuelve JSON exacto:
{ "score": 1-5, "omite_info_critica": true|false, "omisiones": ["..."], "razonamiento": "..." }`;

// Juez de contradicciones (GPT-4o mini): hay contradicciones internas?
const contradiccionesPrompt = `Eres juez de RAG. Te paso pasajes + respuesta.
Evalua SOLO si la respuesta tiene contradicciones internas O contradice los pasajes en sentido logico.
NO chequees numeros exactos (eso lo hacemos en codigo). Solo: "¿hay contradicciones?"

Devuelve JSON exacto:
{ "score": 1-5, "hay_contradicciones": true|false, "contradicciones": ["..."], "razonamiento": "..." }`;

const userPrompt = `PREGUNTA:\n${pregunta}\n\nPASAJES RECUPERADOS:\n${contexto}\n\nRESPUESTA A EVALUAR:\n${respuesta}`;

const [judgeCompletitud, judgeContradicciones] = await Promise.all([
  boundCall('anthropic/claude-sonnet-4', completitudPrompt, userPrompt),
  boundCall('openai/gpt-4o-mini', contradiccionesPrompt, userPrompt),
]);

// === AGREGACION ===

const softProblems = [];
if (judgeCompletitud.omite_info_critica && Array.isArray(judgeCompletitud.omisiones))
  judgeCompletitud.omisiones.forEach(o => o && softProblems.push(`omision: ${o}`));
if (judgeContradicciones.hay_contradicciones && Array.isArray(judgeContradicciones.contradicciones))
  judgeContradicciones.contradicciones.forEach(c => c && softProblems.push(`contradiccion: ${c}`));

const hardProblems = [];
citasInvalidas.forEach(c => hardProblems.push(`cita invalida: ${c.cita}`));
numerosNoEncontrados.forEach(n => hardProblems.push(`numero no esta en contexto: ${n.numero}`));
// Las entidades no-encontradas son menos criticas (regex tiene falsos positivos) - solo warning

let veredicto;
if (!hardOk) {
  veredicto = 'no_fundamentada';
} else if (softProblems.length > 0) {
  veredicto = 'con_observaciones';
} else {
  veredicto = 'fundamentada';
}

const softScores = [judgeCompletitud.score, judgeContradicciones.score].filter(s => typeof s === 'number');
const scorePromedio = softScores.length ? softScores.reduce((a,b)=>a+b,0)/softScores.length : (hardOk ? 5 : 1);

return [{ json: {
  veredicto,
  score_promedio: Number(scorePromedio.toFixed(2)),
  hard_score: hardScore,
  hard_checks: {
    citas: checkCitas,
    numeros: checkNumeros,
    entidades: checkEntidades.slice(0, 20), // limitar para no inflar respuesta
  },
  hard_problems: hardProblems,
  soft_problems: softProblems,
  jueces: [
    { aspecto: 'completitud', ...judgeCompletitud },
    { aspecto: 'contradicciones', ...judgeContradicciones },
  ],
}}];
